//! 🎟️ One stable budget slot retains the pooled row while its actual decoder carries a movable nominal loan.
use super::*;
pub struct OriginalReturnScopeLoan<I:OriginalReturnOrigin>{budget:usize,source:usize,serial:u64,returned:bool,_origin:std::marker::PhantomData<fn()->I>}
impl<I:OriginalReturnOrigin> OriginalReturnScopeLoan<I>{pub fn terminal_is_empty(&self)->bool{self.returned}}
impl<I:OriginalReturnOrigin> Drop for OriginalReturnScopeLoan<I>{fn drop(&mut self){assert!(std::thread::panicking()||self.returned,"original receiving scope must return its pooled Source loan")}}
pub(crate) struct OriginalReturnScope<I:OriginalReturnOrigin>{claim:Option<OriginalReturnStockClaim<I>>,witness:Option<OriginalReturnStockWitness<I>>,actual:A,unused:A,already_observed:P,posted:bool,reserved_progress:P,reserved_work:u64,retirement_required:bool,running:bool}
impl<I:OriginalReturnOrigin> OriginalReturnScope<I>{pub const fn empty()->Self{Self{claim:None,witness:None,actual:A{items:0,copy_bytes:0,capacity_bytes:0,release_bytes:0,work:0},unused:A{items:0,copy_bytes:0,capacity_bytes:0,release_bytes:0,work:0},already_observed:P{copied_items:0,copied_bytes:0,retained_capacity_bytes:0,released_bytes:0},posted:false,reserved_progress:P{copied_items:0,copied_bytes:0,retained_capacity_bytes:0,released_bytes:0},reserved_work:0,retirement_required:false,running:false}}}
fn maximum(a:A,b:A)->A{A{items:a.items.max(b.items),copy_bytes:a.copy_bytes.max(b.copy_bytes),capacity_bytes:a.capacity_bytes.max(b.capacity_bytes),release_bytes:a.release_bytes.max(b.release_bytes),work:a.work.max(b.work)}}
pub fn original_return_scope_admission_copy_bytes<I:OriginalReturnOrigin>()->usize{original_return_stock_claim_copy_bytes::<I>()+std::mem::size_of::<Option<OriginalReturnScopeLoan<I>>>()}
pub fn original_return_scope_completion_copy_bytes<I:OriginalReturnOrigin>(done:bool,local:bool)->usize{original_return_stock_settlement_copy_bytes::<I>(done,local)+2*std::mem::size_of::<A>()+4*std::mem::size_of::<bool>()+2*std::mem::size_of::<P>()+std::mem::size_of::<u64>()}
impl<I:OriginalReturnOrigin> OriginalReturnBudget<I>{
 fn qualify_scope(&self,loan:&OriginalReturnScopeLoan<I>)->Result<(),ValueError>{let origin=self.origin.ok_or_else(bad)?;let claim=self.scope.claim.as_ref().ok_or_else(bad)?;if loan.returned||loan.budget!=self as*const Self as usize||loan.source!=origin.source_identity()||loan.serial!=claim.serial(){return Err(bad())}self.qualify_stock_destination(claim,std::ptr::addr_of!(self.scope)as usize,std::mem::size_of::<OriginalReturnScope<I>>())}
 /// 🌱️ Admits or tops up only the same stable row; returned metadata must be posted by the genuine Source.
 pub fn admit_scope(&mut self,loan:&mut Option<OriginalReturnScopeLoan<I>>,wanted:A,epoch:u64)->Result<Option<(P,u64)>,ValueError>{
  let destination=std::ptr::addr_of!(self.scope)as usize;let extent=std::mem::size_of::<OriginalReturnScope<I>>();
  if let Some(loan)=loan.as_ref(){self.qualify_scope(loan)?;if self.scope.running||self.scope.witness.is_some(){return Err(bad())}let claim=self.scope.claim.as_ref().unwrap();let remaining=self.stock_remaining(claim)?;let additional=sub(maximum(remaining,wanted),remaining)?;if additional==A::default(){return Ok(Some((P::default(),0)))}let claim=self.scope.claim.take().unwrap();let result=self.top_up_stock(&claim,destination,extent,additional);self.scope.claim=Some(claim);result?;return Ok(Some((P{copied_items:1,copied_bytes:original_return_stock_top_up_copy_bytes(),..Default::default()},1)))}
  if self.scope.claim.is_some()||self.scope.witness.is_some()||self.scope.running{return Err(bad())}let copy=original_return_scope_admission_copy_bytes::<I>();let(g,fuel)=self.remaining()?;let needed=progress(wanted)?;if g.maximum_items<needed.copied_items.checked_add(2).ok_or_else(bad)?||g.maximum_copy_bytes<needed.copied_bytes.checked_add(copy).ok_or_else(bad)?||fuel<wanted.work.checked_add(2).ok_or_else(bad)?{return Err(bad())}
  let Some(claim)=self.claim_stock(destination,extent,epoch,wanted)?else{return Ok(None)};let origin=self.origin.unwrap();let serial=claim.serial();self.scope.claim=Some(claim);*loan=Some(OriginalReturnScopeLoan{budget:self as*const Self as usize,source:origin.source_identity(),serial,returned:false,_origin:std::marker::PhantomData});Ok(Some((P{copied_items:2,copied_bytes:copy,..Default::default()},2)))
 }
 /// 🔭️ Reads only genuine unspent row stock, never fresh Source currency.
 pub fn scope_remaining(&self,loan:&OriginalReturnScopeLoan<I>)->Result<A,ValueError>{self.qualify_scope(loan)?;if self.scope.witness.is_some(){return Err(bad())}self.stock_remaining(self.scope.claim.as_ref().unwrap())}
 /// 🚪️ Marks the actual native loan as entered before its callback can produce an effect.
 pub fn enter_scope(&mut self,loan:&OriginalReturnScopeLoan<I>)->Result<(),ValueError>{self.qualify_scope(loan)?;if self.scope.running||self.scope.witness.is_some(){return Err(bad())}self.scope.running=true;Ok(())}
 /// 🧾️ Applies one cumulative receipt and retains its original observation in the stable budget.
 pub fn finish_scope(&mut self,loan:&OriginalReturnScopeLoan<I>,actual:A,release_unused:bool,already_observed:P,reserved_progress:P,reserved_work:u64,retains_output:bool)->Result<(),ValueError>{
  self.qualify_scope(loan)?;if !self.scope.running||self.scope.witness.is_some(){return Err(bad())}if reserved_work>actual.work||source_fresh_progress(progress(actual)?,reserved_progress).is_none(){return Err(bad())}let total=add(self.scope.actual,actual)?;let retirement_required=self.scope.retirement_required||retains_output||actual.capacity_bytes!=0;let claim=self.scope.claim.as_ref().unwrap();let unused=if release_unused&&!retirement_required{add(self.scope.unused,sub(self.stock_remaining(claim)?,actual)?)?}else{self.scope.unused};
  let mut claim=self.scope.claim.take().unwrap();let result=self.settle_stock(&mut claim,total,unused);self.scope.claim=Some(claim);let witness=result?;self.scope.actual=total;self.scope.unused=unused;self.scope.retirement_required=retirement_required;self.scope.witness=witness;self.scope.already_observed=already_observed;self.scope.posted=false;self.scope.reserved_progress=reserved_progress;self.scope.reserved_work=reserved_work;self.scope.running=false;Ok(())
 }
 /// 🧷️ Reports custody that requires actual recipient retirement rather than a numeric release comparison.
 pub fn scope_requires_retirement(&self,loan:&OriginalReturnScopeLoan<I>)->Result<bool,ValueError>{self.qualify_scope(loan)?;Ok(self.scope.retirement_required)}
 /// 📦️ Moves the same opaque credit into a preborn destination after Context qualifies its actual native recipient.
 pub fn transfer_scope_credit(&mut self,loan:&mut OriginalReturnScopeLoan<I>,target:&mut Option<OriginalReturnStockClaim<I>>)->Result<(),ValueError>{self.qualify_scope(loan)?;if target.is_some()||self.scope.running||self.scope.witness.is_some()||!self.scope.retirement_required{return Err(bad())}let from=std::ptr::addr_of!(self.scope)as usize;let claim=self.scope.claim.take().ok_or_else(bad)?;if let Err(error)=self.rebind_stock_destination(&claim,from,target as*const Option<OriginalReturnStockClaim<I>>as usize,std::mem::size_of::<Option<OriginalReturnStockClaim<I>>>()){self.scope.claim=Some(claim);return Err(error)}*target=Some(claim);loan.returned=true;self.scope=OriginalReturnScope::empty();Ok(())}
 /// 🏁️ Retires the decoder's own scope once every output it served has retired: settles the whole unspent hold and its only Source observation, `true` once the stock is gone and the loan is returned.
 pub fn retire_scope(&mut self,loan:&mut OriginalReturnScopeLoan<I>)->Result<bool,ValueError>{
  self.qualify_scope(loan)?;if self.scope.running||self.scope.witness.is_some(){return Err(bad())}
  let mut claim=self.scope.claim.take().ok_or_else(bad)?;
  let settled=(||{if !claim.terminal_is_empty(){let(held,redeemed,_)=self.stock_receipts(&claim)?;let unused=sub(held,redeemed)?;if let Some(mut witness)=self.settle_stock(&mut claim,redeemed,unused)?{self.acknowledge_stock(&mut claim,&mut witness)?}}Ok::<(),ValueError>(())})();
  if let Err(error)=settled{self.scope.claim=Some(claim);return Err(error)}
  let done=claim.terminal_is_empty();if done{loan.returned=true;self.scope=OriginalReturnScope::empty()}else{self.scope.claim=Some(claim)}Ok(done)
 }
 /// 👁️ Borrows the exact original receipt before the actual Source posts its observation.
 pub fn scope_observation(&self,loan:&OriginalReturnScopeLoan<I>)->Result<Option<(P,u64)>,ValueError>{self.qualify_scope(loan)?;Ok(self.scope.witness.as_ref().map(|w|(w.progress(),w.work())))}
 pub fn scope_observer_state(&self,loan:&OriginalReturnScopeLoan<I>)->Result<(P,bool,P,u64),ValueError>{self.qualify_scope(loan)?;Ok((self.scope.already_observed,self.scope.posted,self.scope.reserved_progress,self.scope.reserved_work))}
 pub fn mark_scope_observed(&mut self,loan:&OriginalReturnScopeLoan<I>)->Result<(),ValueError>{self.qualify_scope(loan)?;if self.scope.witness.is_none()||self.scope.posted{return Err(bad())}self.scope.posted=true;Ok(())}
 pub fn acknowledge_scope(&mut self,loan:&mut OriginalReturnScopeLoan<I>)->Result<bool,ValueError>{self.qualify_scope(loan)?;if self.scope.running||self.scope.witness.is_some()&&!self.scope.posted{return Err(bad())}let mut claim=self.scope.claim.take().unwrap();if let Some(mut witness)=self.scope.witness.take(){let result=self.acknowledge_stock(&mut claim,&mut witness);if let Err(error)=result{self.scope.claim=Some(claim);self.scope.witness=Some(witness);return Err(error)}}let done=claim.terminal_is_empty();if done{loan.returned=true;self.scope=OriginalReturnScope::empty()}else{self.scope.claim=Some(claim)}Ok(done)}
}

/// 📏️ Quotes the next actual owner phase; setup progress never enters the native callback.
pub fn original_return_scope_setup_demand(bound:bool,table:bool)->Option<(usize,semio_framework_value_retained_clone::RetirementDemand,u64)>{if !bound{return Some((1,semio_framework_value_retained_clone::RetirementDemand{depth:1,..Default::default()},1))}if table{return None}let(copy,capacity,work)=OriginalReturnEscrowTable::birth_demand();Some((1,semio_framework_value_retained_clone::RetirementDemand{copy_bytes:copy,capacity_bytes:capacity,release_bytes:capacity,depth:1},work))}

/// 📊️ The genuine Context lends its actual accounting destinations; this data view mints no authority.
pub struct OriginalReturnScopeCounters<'a>{pub physical:&'a mut P,pub work:&'a mut u128,pub fuel:&'a mut u64,pub reserved:&'a mut P,pub reserved_work:&'a mut u64,pub aggregate_physical:Option<(&'a P,P)>,pub aggregate_work:Option<&'a u128>,pub reserved_observer:Option<(&'a mut P,&'a mut u128)>,pub grant:RetainedCloneGrant}
impl<I:OriginalReturnOrigin> OriginalReturnBudget<I>{
 /// 🫴️ Reconciles the same original receipt before acknowledging its only real Source observation.
 pub fn observe_scope(&mut self,loan:&mut OriginalReturnScopeLoan<I>,mut counters:OriginalReturnScopeCounters<'_>)->Result<bool,ValueError>{
  let Some((total,work))=self.scope_observation(loan)?else{return Ok(false)};let(already,posted,reserved_progress,reserved_work)=self.scope_observer_state(loan)?;
  if !posted{let extra=source_fresh_progress(total,already).ok_or_else(bad)?;let fresh_work=work.checked_sub(reserved_work).ok_or_else(bad)?;let reserved_extra=P{copied_items:extra.copied_items.min(reserved_progress.copied_items),copied_bytes:extra.copied_bytes.min(reserved_progress.copied_bytes),retained_capacity_bytes:extra.retained_capacity_bytes.min(reserved_progress.retained_capacity_bytes),released_bytes:extra.released_bytes.min(reserved_progress.released_bytes)};if fresh_work>*counters.fuel||!source_fresh_progress(extra,reserved_extra).ok_or_else(bad)?.fits(counters.grant){return Err(bad())}let physical=counters.physical.checked_add(extra)?;let actual_work=counters.work.checked_add(u128::from(work)).ok_or_else(bad)?;if let Some((recipient,start))=counters.aggregate_physical{recipient.checked_add(source_fresh_progress(*counters.physical,start).ok_or_else(bad)?)?.checked_add(extra)?;}if let Some(recipient)=counters.aggregate_work{recipient.checked_add(actual_work).ok_or_else(bad)?;}let reserved=counters.reserved.checked_add(reserved_progress)?;let reserved_cpu=counters.reserved_work.checked_add(reserved_work).ok_or_else(bad)?;let observed=match counters.reserved_observer.as_ref(){Some((progress,fuel))=>Some((progress.checked_add(reserved_progress)?,fuel.checked_add(u128::from(reserved_work)).ok_or_else(bad)?)),None=>None};
   *counters.physical=physical;*counters.work=actual_work;*counters.reserved=reserved;*counters.reserved_work=reserved_cpu;*counters.fuel-=fresh_work;if let(Some((target,work)),Some((progress,fuel)))=(counters.reserved_observer.as_mut(),observed){**target=progress;**work=fuel}self.mark_scope_observed(loan)?;
  }self.acknowledge_scope(loan)
 }
}
/// 📏️ The plan contains only quotes; the same row still has to fund every amount before entry.
pub struct OriginalReturnScopePlan{pub wanted:A,pub control:P,pub control_work:u64,pub quantum:RetainedCloneGrant,pub quantum_work:u64,pub recovering_pending:bool,pub setup:P,pub setup_work:u64,pub ready:bool}
impl OriginalReturnScopePlan{
 /// 🌓️ A scope claims exactly its quoted need in one turn and is ready in that same call, or claims nothing: a turn that cannot afford the whole need is denied and charges nothing.
 pub fn quote<I:OriginalReturnOrigin>(fresh:RetainedCloneGrant,quantum:RetainedCloneGrant,fresh_work:u64,quantum_work:u64,existing:A,loaned:bool,pending:u64,pending_actions:bool,retirement:bool,local:bool,outcome:P,outcome_work:u64)->Result<Option<Self>,ValueError>{
  let control=P{copied_items:outcome.copied_items.checked_add(2).ok_or_else(bad)?,copied_bytes:outcome.copied_bytes.checked_add(original_return_scope_completion_copy_bytes::<I>(true,local)).and_then(|v|v.checked_add(std::mem::size_of::<Option<OriginalReturnScopeLoan<I>>>())).ok_or_else(bad)?,..Default::default()};let control_work=4u64.checked_add(outcome_work).ok_or_else(bad)?;let recovering_pending=retirement&&pending_actions;
  let(setup,setup_work)=if loaned{(P{copied_items:1,copied_bytes:original_return_stock_top_up_copy_bytes(),..Default::default()},1)}else{(P{copied_items:2,copied_bytes:original_return_scope_admission_copy_bytes::<I>(),..Default::default()},2)};
  let(target,quantum_work)=if recovering_pending{if existing.items<control.copied_items as u64||existing.copy_bytes<control.copied_bytes as u64||existing.work<pending.checked_add(control_work).ok_or_else(bad)?{return Ok(None)}(existing,0)}else{if quantum.maximum_items==0||quantum.maximum_depth==0||quantum_work==0{return Ok(None)}
   let exact=|fresh:u64,have:u64,quote:u64,control:u64|quote.saturating_add(control).min(fresh.saturating_add(have));
   (A{items:exact((fresh.maximum_items as u64).saturating_sub(setup.copied_items as u64),existing.items,quantum.maximum_items as u64,2*control.copied_items as u64),copy_bytes:exact((fresh.maximum_copy_bytes as u64).saturating_sub(setup.copied_bytes as u64),existing.copy_bytes,quantum.maximum_copy_bytes as u64,2*control.copied_bytes as u64),capacity_bytes:exact(fresh.maximum_capacity_bytes as u64,existing.capacity_bytes,quantum.maximum_capacity_bytes as u64,0),release_bytes:exact(fresh.maximum_release_bytes as u64,existing.release_bytes,quantum.maximum_release_bytes as u64,0),work:exact(fresh_work.saturating_sub(setup_work),existing.work,quantum_work,2*control_work)},quantum_work)};
  let full=A{items:(quantum.maximum_items as u64).saturating_add(2*control.copied_items as u64),copy_bytes:(quantum.maximum_copy_bytes as u64).saturating_add(2*control.copied_bytes as u64),capacity_bytes:quantum.maximum_capacity_bytes as u64,release_bytes:quantum.maximum_release_bytes as u64,work:quantum_work.saturating_add(2*control_work)};let covers=|have:A|recovering_pending||have.items>=full.items&&have.copy_bytes>=full.copy_bytes&&have.capacity_bytes>=full.capacity_bytes&&have.release_bytes>=full.release_bytes&&have.work>=full.work;let viable=loaned&&existing.items>2*control.copied_items as u64&&existing.copy_bytes>=2*control.copied_bytes as u64&&existing.work>2*control_work&&covers(existing);let running=|wanted:A|Self{wanted,control,control_work,quantum,quantum_work,recovering_pending,setup:P::default(),setup_work:0,ready:true};
  let need=sub(maximum(target,existing),existing)?;if loaned&&need==A::default()&&covers(existing){return Ok(Some(running(existing)))}
  if !setup.fits(fresh)||fresh_work<setup_work||fresh.maximum_depth==0{return Ok(viable.then(||running(existing)))}let free=source_fresh_progress(P{copied_items:fresh.maximum_items,copied_bytes:fresh.maximum_copy_bytes,retained_capacity_bytes:fresh.maximum_capacity_bytes,released_bytes:fresh.maximum_release_bytes},setup).ok_or_else(bad)?;
  if need.items>free.copied_items as u64||need.copy_bytes>free.copied_bytes as u64||need.capacity_bytes>free.retained_capacity_bytes as u64||need.release_bytes>free.released_bytes as u64||need.work>fresh_work-setup_work{return Ok(viable.then(||running(existing)))}
  let wanted=add(existing,need)?;let ready=wanted.items>2*control.copied_items as u64&&wanted.copy_bytes>=2*control.copied_bytes as u64&&wanted.work>2*control_work&&covers(wanted);
  if !ready{return Ok(viable.then(||running(existing)))}
  Ok(Some(Self{wanted,control,control_work,quantum,quantum_work,recovering_pending,setup,setup_work,ready}))
 }
 pub fn body(&self,pooled:A)->Result<(RetainedCloneGrant,u64),ValueError>{if !self.ready{return Err(bad())}if self.recovering_pending{return Ok((RetainedCloneGrant{maximum_items:native(pooled.items)?,maximum_copy_bytes:native(pooled.copy_bytes)?,maximum_capacity_bytes:native(pooled.capacity_bytes)?,maximum_release_bytes:native(pooled.release_bytes)?,maximum_depth:self.quantum.maximum_depth},0))}Ok((RetainedCloneGrant{maximum_items:native(pooled.items)?.saturating_sub(2*self.control.copied_items).min(self.quantum.maximum_items),maximum_copy_bytes:native(pooled.copy_bytes)?.saturating_sub(2*self.control.copied_bytes).min(self.quantum.maximum_copy_bytes),maximum_capacity_bytes:native(pooled.capacity_bytes)?.min(self.quantum.maximum_capacity_bytes),maximum_release_bytes:native(pooled.release_bytes)?.min(self.quantum.maximum_release_bytes),maximum_depth:self.quantum.maximum_depth},pooled.work.saturating_sub(2*self.control_work).min(self.quantum_work)))}
}

/// 📐️ Reads the already admitted turn and policy ceilings without consulting or issuing fresh Source stock.
pub fn original_return_scope_quantum(progress:P,reserved:P,grant:RetainedCloneGrant,policy:Option<(RetainedCloneGrant,P)>)->RetainedCloneGrant{let Some(current)=source_fresh_progress(progress,reserved)else{return RetainedCloneGrant::default()};let remaining=|grant:RetainedCloneGrant,p:P|RetainedCloneGrant{maximum_items:grant.maximum_items.saturating_sub(p.copied_items),maximum_copy_bytes:grant.maximum_copy_bytes.saturating_sub(p.copied_bytes),maximum_capacity_bytes:grant.maximum_capacity_bytes.saturating_sub(p.retained_capacity_bytes),maximum_release_bytes:grant.maximum_release_bytes.saturating_sub(p.released_bytes),..grant};let g=remaining(grant,current);match policy{None=>g,Some((policy,start))=>{let p=remaining(policy,source_fresh_progress(current,start).unwrap_or_default());RetainedCloneGrant{maximum_items:g.maximum_items.min(p.maximum_items),maximum_copy_bytes:g.maximum_copy_bytes.min(p.maximum_copy_bytes),maximum_capacity_bytes:g.maximum_capacity_bytes.min(p.maximum_capacity_bytes),maximum_release_bytes:g.maximum_release_bytes.min(p.maximum_release_bytes),maximum_depth:g.maximum_depth.min(p.maximum_depth)}}}}

/// 📏️ Prices both actual credit placements and the stable scope reset before custody moves.
pub fn original_return_scope_transfer_copy_bytes<I:OriginalReturnOrigin>()->usize{2*std::mem::size_of::<Option<OriginalReturnStockClaim<I>>>()+std::mem::size_of::<OriginalReturnScope<I>>()+std::mem::size_of::<Option<OriginalReturnScopeLoan<I>>>()+std::mem::size_of::<bool>()}

/// 🏦️ A constructed output owns the scope credit its consumed payload held; the credit settles once, when the output has retired, at the rebound destination.
pub struct CreditedOutput<I:OriginalReturnOrigin,O>{output:Option<O>,credit:Box<Option<OriginalReturnStockClaim<I>>>}
impl<I:OriginalReturnOrigin,O> CreditedOutput<I,O>{
 pub fn adopt(output:O,budget:&mut OriginalReturnBudget<I>,loan:&mut OriginalReturnScopeLoan<I>)->Result<Self,(ValueError,O)>{let mut credit=Box::new(None);match budget.transfer_scope_credit(loan,&mut credit){Ok(())=>Ok(Self{output:Some(output),credit}),Err(error)=>Err((error,output))}}
 /// ✂️ Separates the output from its credit so the credit can follow another owner.
 pub fn split(self)->(Option<O>,CreditedOutput<I,()>){(self.output,CreditedOutput{output:None,credit:self.credit})}
 pub fn output(&self)->Option<&O>{self.output.as_ref()}
 pub fn output_mut(&mut self)->Option<&mut O>{self.output.as_mut()}
 pub fn take_output(&mut self)->Option<O>{self.output.take()}
 /// 🧾️ Settles the whole unspent hold and its only Source observation; `true` once the credit is gone.
 pub fn settle_credit(&mut self,budget:&mut OriginalReturnBudget<I>)->Result<bool,ValueError>{
  let Some(claim)=self.credit.as_mut()else{return Ok(true)};
  if !claim.terminal_is_empty(){let(held,redeemed,_)=budget.stock_receipts(claim)?;let unused=sub(held,redeemed)?;if let Some(mut witness)=budget.settle_stock(claim,redeemed,unused)?{budget.acknowledge_stock(claim,&mut witness)?}}
  if claim.terminal_is_empty(){*self.credit=None;return Ok(true)}Ok(false)
 }
 pub fn terminal_is_empty(&self)->bool{self.output.is_none()&&self.credit.is_none()}
}
